#!/bin/sh
# Truthstone for Codex: hook launcher. GENERATED by truthstone.adapters.codex.plugin -- do not edit.
#
# Codex runs every Truthstone hook as:  /bin/sh "${PLUGIN_ROOT}/hooks/truthstone-hook.sh" <event>
# with the hook payload on stdin. This script only finds the Truthstone runtime and hands the
# payload to it; all logic lives in the runtime, so upgrading Truthstone never changes this
# plugin (Codex makes you re-trust a plugin's hooks whenever any of its files change).
#
# Lookup order: $TRUTHSTONE_CODEX_HOOK, then `truthstone-codex-hook` on PATH, then a private copy in
# Codex's per-plugin data directory ($PLUGIN_DATA), which the session-start hook installs
# with uv on first use (set TRUTHSTONE_NO_BOOTSTRAP=1 to prevent that).
#
# It always exits 0. Codex reads exit code 2 as "block this", and a launcher problem must
# never block the developer's work.

# rename-tool: keep-begin former-settings (settings under a former product name still apply)
[ -n "${TRUTHSTONE_CODEX_HOOK:-}" ] || [ -z "${AGENTGUARD_CODEX_HOOK+x}" ] || TRUTHSTONE_CODEX_HOOK=$AGENTGUARD_CODEX_HOOK
[ -n "${TRUTHSTONE_DISABLE:-}" ] || [ -z "${AGENTGUARD_DISABLE+x}" ] || TRUTHSTONE_DISABLE=$AGENTGUARD_DISABLE
[ -n "${TRUTHSTONE_NO_BOOTSTRAP:-}" ] || [ -z "${AGENTGUARD_NO_BOOTSTRAP+x}" ] || TRUTHSTONE_NO_BOOTSTRAP=$AGENTGUARD_NO_BOOTSTRAP
[ -n "${TRUTHSTONE_SOURCE:-}" ] || [ -z "${AGENTGUARD_SOURCE+x}" ] || TRUTHSTONE_SOURCE=$AGENTGUARD_SOURCE
# rename-tool: keep-end

event="${1:-}"
case "${TRUTHSTONE_DISABLE:-}" in 1|true|TRUE|True|yes|on) exit 0 ;; esac

runtime_source="${TRUTHSTONE_SOURCE:-git+https://github.com/tohin003/Truthstone@v0.1.0-dev.0}"
private="${PLUGIN_DATA:-}/runtime"
runner=""
if [ -n "${TRUTHSTONE_CODEX_HOOK:-}" ] && [ -x "$TRUTHSTONE_CODEX_HOOK" ]; then
  runner="$TRUTHSTONE_CODEX_HOOK"
elif command -v truthstone-codex-hook >/dev/null 2>&1; then
  runner="truthstone-codex-hook"
elif [ -n "${PLUGIN_DATA:-}" ] && [ -x "$private/bin/truthstone-codex-hook" ]; then
  runner="$private/bin/truthstone-codex-hook"
fi

if [ "$event" = "session-start" ] && [ -n "${PLUGIN_DATA:-}" ] && [ -z "${TRUTHSTONE_NO_BOOTSTRAP:-}" ] \
  && [ "$runner" = "$private/bin/truthstone-codex-hook" -o -z "$runner" ] \
  && [ "$(cat "$private/source" 2>/dev/null)" != "$runtime_source" ] && command -v uv >/dev/null 2>&1; then
  # Install (or re-install, when the source changed) a private runtime. Never onto PATH,
  # never inside the plugin root. Output goes to a log, not to Codex.
  mkdir -p "$private" 2>/dev/null
  if UV_TOOL_DIR="$private/tools" UV_TOOL_BIN_DIR="$private/bin" \
    uv tool install --quiet --reinstall "$runtime_source" </dev/null >>"$private/install.log" 2>&1; then
    printf '%s' "$runtime_source" >"$private/source"
  fi
  [ -x "$private/bin/truthstone-codex-hook" ] && runner="$private/bin/truthstone-codex-hook"
fi

if [ -z "$runner" ]; then
  if [ "$event" = "session-start" ]; then
    printf '%s\n' '{"systemMessage": "Truthstone is installed as a Codex plugin, but its runtime was not found, so this session is UNGUARDED. Install it with: uv tool install git+https://github.com/tohin003/Truthstone@v0.1.0-dev.0  (or put truthstone-codex-hook on PATH), then start a new session."}'
  fi
  exit 0
fi

"$runner" "$event"
exit 0
